// Standalone exporter of the enriched CPA catalogue to omp's models.yml. No Pi needed.
//   node --experimental-strip-types src/omp-cli.ts [--connection ID] [--agent-dir DIR] [--bundled FILE] [--local FILE] [--write] [--force]
// Default is a preview on stdout. --write replaces <agent-dir>/models.yml (the old file is kept as models.yml.backup-*);
// a models.yml that was not generated by this tool is refused unless --force.
import { readFile } from 'node:fs/promises';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ProxyFault, readLayers, safeFailure, userConfigPath, writePrivateFile } from './configuration.ts';
import { OMP_MANAGED_MARKER, catalogueFor, ompModelsYml } from './omp-export.ts';

interface Options { connection?: string; agentDir: string; bundled: string; local: string; write: boolean; force: boolean }

export function parseArguments(argv: string[], env: NodeJS.ProcessEnv = process.env): Options {
  const options: Options = {
    agentDir: env.OMP_AGENT_DIR ?? env.PI_CODING_AGENT_DIR ?? join(homedir(), '.omp', 'agent'),
    bundled: fileURLToPath(new URL('../config.yaml', import.meta.url)),
    local: userConfigPath(), write: false, force: false,
  };
  const value = (index: number) => { if (argv[index + 1] === undefined) throw new ProxyFault('omp_cli_missing_value'); return argv[index + 1]; };
  for (let index = 0; index < argv.length; index++) {
    const flag = argv[index];
    if (flag === '--write') options.write = true;
    else if (flag === '--force') options.force = true;
    else if (flag === '--connection') options.connection = value(index++);
    else if (flag === '--agent-dir') options.agentDir = value(index++);
    else if (flag === '--bundled') options.bundled = value(index++);
    else if (flag === '--local') options.local = value(index++);
    else throw new ProxyFault('omp_cli_unknown_argument');
  }
  return options;
}

export async function run(argv: string[], out: (text: string) => void = (text) => process.stdout.write(text)): Promise<void> {
  const options = parseArguments(argv);
  const { config } = await readLayers(options.bundled, options.local);
  const connections = Object.entries(config?.connections ?? {});
  if (!connections.length) throw new ProxyFault('omp_connections_missing');
  const target = options.connection ? connections.find(([id]) => id === options.connection) : connections.length === 1 ? connections[0] : undefined;
  if (!target) throw new ProxyFault(options.connection ? 'omp_connection_unknown' : 'omp_connection_ambiguous');
  const [id, gateway] = target;
  const models = await catalogueFor(id, gateway, join(dirname(options.local), 'cache'));
  if (!models.length) throw new ProxyFault('omp_catalogue_empty');
  const yaml = ompModelsYml(id, gateway, models);
  if (!options.write) { out(yaml); return; }
  const path = join(options.agentDir, 'models.yml');
  let existing: string | undefined;
  try { existing = await readFile(path, 'utf8'); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw new ProxyFault('omp_target_unreadable'); }
  if (existing !== undefined && !existing.includes(OMP_MANAGED_MARKER) && !options.force) throw new ProxyFault('omp_target_not_managed');
  await writePrivateFile(path, yaml);
  out(`written ${path} (${models.length} models from ${id}); restart omp or run \`omp models refresh\`\n`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  run(process.argv.slice(2)).catch((error) => { process.stderr.write(`cpa-omp: ${safeFailure(error)}\n`); process.exit(1); });
}
